insert into public.konkur_news (id,title,summary,body,source_name,source_url,source_published_at,status,published_at) values
  ('a2d87631-c0a7-4ab6-8e0d-000000000001', 'نتایج اولیه کنکور سراسری ۱۴۰۵ منتشر شد', 'خبرگزاری مهر از انتشار نتایج اولیه کنکور ۱۴۰۵ در سایت سازمان سنجش خبر داد.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "به گزارش خبرگزاری مهر در ۱۱ مهر ۱۴۰۵، نتایج اولیه آزمون سراسری سال ۱۴۰۵ روی سایت سازمان سنجش آموزش کشور منتشر شد."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "در گزارش مهر، بازه اولیه انتخاب رشته از ۱۳ تا ۱۶ مهر و امکان انتخاب ۱۵۰ کدرشته‌محل اعلام شده بود. این بازه مربوط به تاریخ انتشار خبر است؛ برای تمدید احتمالی یا اطلاعیه جدید، سایت سازمان سنجش را بررسی کنید."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "بر اساس اظهارات رئیس سازمان سنجش در این گزارش، زمان اعلام نتایج نهایی اواسط آبان پیش‌بینی شده است؛ این زمان را به‌عنوان وعده گزارش‌شده، نه اعلام قطعی نتیجه، در نظر بگیرید."}]}]}', 'خبرگزاری مهر', 'https://www.mehrnews.com/news/6966489', '2026-10-03', 'published', now()),
  ('a2d87631-c0a7-4ab6-8e0d-000000000002', 'تأثیر قطعی سوابق یازدهم و دوازدهم در کنکور ۱۴۰۶', 'گزارش مهر، تأثیر قطعی سوابق پایه‌های یازدهم و دوازدهم در کنکور ۱۴۰۶ را تشریح می‌کند.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "خبرگزاری مهر در ۲ مهر ۱۴۰۵ گزارش داد که در آزمون سراسری ۱۴۰۶، سابقه تحصیلی پایه‌های یازدهم و دوازدهم با تأثیر قطعی محاسبه می‌شود."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "در گروه‌های اصلی ریاضی، تجربی و انسانی، مجموع سهم سوابق تحصیلی ۶۰ درصد است. شرایط گروه‌های هنر و زبان‌های خارجی و برخی مشمولان خاص متفاوت است؛ حکم گروه‌های اصلی را به همه داوطلبان تعمیم ندهید."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "این خلاصه درباره کنکور ۱۴۰۶ است و نباید با نحوه اعمال سوابق در کنکور ۱۴۰۵ اشتباه گرفته شود. جزئیات و استثناها را در اطلاعیه رسمی سازمان سنجش و متن منبع بررسی کنید."}]}]}', 'خبرگزاری مهر', 'https://www.mehrnews.com/news/6956825', '2026-09-24', 'published', now()),
  ('a2d87631-c0a7-4ab6-8e0d-000000000003', 'عناوین و ضرایب دروس سوابق تحصیلی کنکور ۱۴۰۶ اعلام شد', 'سازمان سنجش، عناوین دروس و سهم هر پایه در سوابق تحصیلی آزمون سراسری ۱۴۰۶ را اعلام کرد.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "طبق گزارش خبرگزاری مهر در ۱ مهر ۱۴۰۵ از اطلاعیه سازمان سنجش، عناوین و ضرایب دروس سوابق تحصیلی و آزمون اختصاصی کنکور سراسری ۱۴۰۶ اعلام شد."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "برای نظام آموزشی ۶-۳-۳ در گروه‌های اصلی ریاضی، تجربی و انسانی، سهم پایه یازدهم ۱۷ درصد و پایه دوازدهم ۴۳ درصد است؛ سهم آزمون اختصاصی ۴۰ درصد خواهد بود."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "در گروه‌های هنر و زبان‌های خارجی، سهم سوابق تحصیلی ۳۰ درصد و آزمون اختصاصی ۷۰ درصد است و فقط دروس عمومی در سوابق لحاظ می‌شود. برای جدول کامل ضرایب، شرایط نظام سالی‌واحدی و استثناهای داوطلبان، متن اطلاعیه و منبع خبر را بخوانید."}]}]}', 'خبرگزاری مهر', 'https://www.mehrnews.com/news/6955598', '2026-09-23', 'published', now())
